function qa(s,r){return Array.prototype.slice.call((r||document).querySelectorAll(s))}

var PATHWAYS=['Fool','Door','Error','Sun','Tyrant','White Tower','Visionary','Hanged Man','Darkness','Death',
  'Twilight Giant','Red Priest','Demoness','Paragon','Hermit','Mother','Moon','Chained','Abyss','Justiciar',
