  'Twilight Giant':'Warrior','Red Priest':'Hunter','Demoness':'Assassin','Paragon':'Savant','Hermit':'Mystery Pryer',
  'Mother':'Planter','Moon':'Apothecary','Chained':'Prisoner','Abyss':'Criminal','Justiciar':'Arbiter',
