/* TIER GRID */
var TIER_GLYPH='<svg class="tglyph" viewBox="0 0 14 14" fill="none"><circle cx="7" cy="7" r="6" stroke="currentColor" stroke-width="1.1"/><circle cx="7" cy="7" r="1.6" fill="currentColor"/></svg>';
