      '<div class="tn" style="color:var(--tx)">'+t.id+'</div><div class="td">'+t.desc+'</div></div>';
  }).join('');
  qa('.tier-plate').forEach(function(p){
    p.addEventListener('click',function(){curTier=p.getAttribute('data-tier');renderTiers()});
  });
}
renderTiers();

/* PATHWAY SELECT */
var sel=g('f-pathway');
sel.innerHTML='<option value="">No Pathway (Mortal)</option>'+PATHWAYS.map(function(p){return '<option value="'+p+'">'+p+'</option>'}).join('');

/* ASCENSION LADDER (Seq 9 at bottom rising to 0 at top) */
function renderLadder(){
  var rail=g('ladder-rail');
  var h='';
  for(var s=0;s<=9;s++){
    h+='<div class="ladder-node'+(s===curSeq?' on':'')+'" data-seq="'+s+'"></div>';
    if(s<9)h+='<div class="ladder-seg"></div>';
  }
  rail.innerHTML=h;
  qa('.ladder-node',rail).forEach(function(n){
    n.addEventListener('click',function(){curSeq=parseInt(n.getAttribute('data-seq'),10);renderLadder();updatePreview()});
  });
}
function updatePreview(){
  var p=sel.value;
  g('pp-seq').textContent=p?('Sequence '+curSeq):'—';
  g('pp-name').textContent=p||'No Pathway';
  g('pp-title').textContent=p?(curSeq===9?(SEQ9_TITLE[p]||''):'a title yet unwritten'):'';
}
sel.addEventListener('change',updatePreview);
renderLadder();
updatePreview();

/* ALIAS LIST */
function addAlias(){
  aliasCount++;
  var row=document.createElement('div');
  row.className='ac-list-item';
  row.innerHTML='<input type="text" placeholder="A name used elsewhere&#8230;">'+
    '<div class="ac-list-rm">&times;</div>';
