  g('alias-list').appendChild(row);
}
g('alias-add').addEventListener('click',addAlias);

/* ASTRAL DIALS */
var R=23,CIRC=2*Math.PI*R;
function ringSvg(id,v){
  var off=CIRC-(Math.max(0,Math.min(100,v))/100)*CIRC;
  return '<div class="dial-ring-wrap">'+
    '<svg viewBox="0 0 54 54"><circle class="dial-track" cx="27" cy="27" r="'+R+'"/>'+
    '<circle class="dial-fill" id="dr-'+id+'" cx="27" cy="27" r="'+R+'" stroke-dasharray="'+CIRC+'" stroke-dashoffset="'+off+'"/></svg>'+
    '<input type="number" class="dial-input" id="dv-'+id+'" min="0" max="100" value="'+v+'">'+
  '</div>';
}
function renderDials(){
  var wrap=g('dial-grid');
  wrap.innerHTML=STATS.map(function(s){
    var v=statVals[s[0]]!=null?statVals[s[0]]:10;
    statVals[s[0]]=v;
    return '<div class="dial-unit">'+ringSvg(s[0],v)+'<div class="dial-lbl">'+s[1]+'</div></div>';
  }).join('');
  STATS.forEach(function(s){
    var inp=g('dv-'+s[0]);
    if(inp)inp.addEventListener('input',function(){
      var v=parseInt(this.value,10);if(isNaN(v))v=0;
      v=Math.max(0,Math.min(100,v));
      statVals[s[0]]=v;
      var off=CIRC-(v/100)*CIRC;
      g('dr-'+s[0]).style.strokeDashoffset=off;
    });
  });
}
renderDials();

/* TABS */
qa('.actab').forEach(function(t){
  t.addEventListener('click',function(){go(t.getAttribute('data-t'))});
});
qa('.ac-nb[data-next]').forEach(function(n){
  n.addEventListener('click',function(){go(n.getAttribute('data-next'))});
});
function go(target){
  qa('.actab').forEach(function(x){x.classList.toggle('on',x.getAttribute('data-t')===target)});
  qa('.acpanel').forEach(function(p){p.classList.toggle('on',p.getAttribute('data-p')===target)});
}

/* SUBMIT — build JSON, inject into SillyTavern chat input, auto-send */
function sendToST(txt){
  try{
    var w=window.parent||window;
    var ta=w.document.getElementById('send_textarea')||
           w.document.querySelector('textarea.chat-input,#textareaAutosize,textarea');
    if(ta){
      var dd=Object.getOwnPropertyDescriptor(w.HTMLTextAreaElement.prototype,'value');
      if(dd&&dd.set)dd.set.call(ta,txt);else ta.value=txt;
      ta.dispatchEvent(new Event('input',{bubbles:true}));
      setTimeout(function(){
        try{
          var sb=w.document.getElementById('send_but');
          if(sb)sb.click();
          else ta.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));
        }catch(e2){}
      },150);
      return;
    }
  }catch(e){}
  try{navigator.clipboard.writeText(txt);}catch(e2){}
}

