  };
  g('ac-over').classList.add('on');
  var oT='<'+'LOM_CONFIRM'+'>';var cT='<'+'/LOM_CONFIRM'+'>';
  var txt=oT+'\n'+JSON.stringify(data,null,2)+'\n'+cT;
